const taskQuestions = `-- name: TaskQuestions :many
SELECT id,code,kind,project_id,task_id,execution_id,session_id,text,options,asked_by,asked_at,answer,answered_by,answered_at,state::text AS state,
 (data->'artifactIds')::jsonb AS artifact_ids,(data->'cause')::jsonb AS cause,addressed_to
FROM question
WHERE ($1::text IS NULL OR id = $1)
 AND ($2::text IS NULL OR task_id = $2)
 AND ($3::text IS NULL
  OR session_id IN (SELECT s.id FROM session s WHERE s.bot_id = $3 AND s.tombstoned_at IS NULL)
  OR execution_id IN (SELECT e.id FROM execution e WHERE e.bot_id = $3)
  OR EXISTS (SELECT 1 FROM execution e WHERE e.bot_id = $3 AND question.asked_by = 'execution:' || e.id)
  OR task_id IN (SELECT bt.task_id FROM bot_task bt WHERE bt.bot_id = $3 AND bt.tombstoned_at IS NULL))
 AND ($4::text IS NULL OR state::text = $4)
 AND ($5::text IS NULL OR kind::text = $5)
 AND ($6::text[] IS NULL OR project_id = ANY($6::text[]) OR ($7::boolean AND project_id IS NULL))
 AND NOT coalesce(project_id = ANY($8::text[]), false) AND (NOT $9::boolean OR project_id IS NOT NULL)
 AND (NOT $10::boolean OR coalesce(addressed_to, '') NOT LIKE 'bot:%')
ORDER BY seq
LIMIT $11::bigint
`

type TaskQuestionsParams struct {
	ID           *string
	TaskID       *string
	BotID        *string
	State        *string
	Kind         *string
	Projects     []string
	ProjectsNull bool
	Excluded     []string
	ExcludeNull  bool
	PeopleOnly   bool
	Lim          *int64
}

type TaskQuestionsRow struct {
	ID          string
	Code        *string
	Kind        QuestionKind
	ProjectID   *string
	TaskID      *string
	ExecutionID *string
	SessionID   *string
	Text        string
	Options     []byte
	AskedBy     *string
	AskedAt     time.Time
	Answer      *string
	AnsweredBy  *string
	AnsweredAt  *time.Time
	State       string
	ArtifactIds []byte
	Cause       []byte
	AddressedTo *string
}

// Question rows (questions_list): each filter optional; projects keeps those projects (projects_null: and questions
// outside projects), excluded leaves those out (exclude_null: and questions outside projects).
func (q *Queries) TaskQuestions(ctx context.Context, arg TaskQuestionsParams) ([]TaskQuestionsRow, error) {
	rows, err := q.db.Query(ctx, taskQuestions,
		arg.ID,
		arg.TaskID,
		arg.BotID,
		arg.State,
		arg.Kind,
		arg.Projects,
		arg.ProjectsNull,
		arg.Excluded,
		arg.ExcludeNull,
		arg.PeopleOnly,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TaskQuestionsRow
	for rows.Next() {
		var i TaskQuestionsRow
		if err := rows.Scan(
			&i.ID,
			&i.Code,
			&i.Kind,
			&i.ProjectID,
			&i.TaskID,
			&i.ExecutionID,
			&i.SessionID,
			&i.Text,
			&i.Options,
			&i.AskedBy,
			&i.AskedAt,
			&i.Answer,
			&i.AnsweredBy,
			&i.AnsweredAt,
			&i.State,
			&i.ArtifactIds,
			&i.Cause,
			&i.AddressedTo,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

